begin;
alter table public.staff add column if not exists portal_enabled boolean not null default false;
alter table public.staff add column if not exists portal_activated_at timestamptz;
alter table public.staff add column if not exists portal_invitation_sent_at timestamptz;
create or replace function public.set_staff_portal_activation(p_staff_id uuid,p_enabled boolean,p_reason text) returns void language plpgsql security definer set search_path=public as $$ begin if not public.can_administer() then raise exception 'Acceso administrativo requerido.'; end if; if nullif(trim(p_reason),'') is null then raise exception 'La razón del cambio es obligatoria.'; end if; update public.staff set portal_enabled=p_enabled,portal_activated_at=case when p_enabled then coalesce(portal_activated_at,now()) end,updated_by=auth.uid(),approval_reason=p_reason where id=p_staff_id and deleted_at is null; if not found then raise exception 'Staff no encontrado.'; end if; if not p_enabled then update public.portal_access_sessions set revoked_at=now() where staff_id=p_staff_id and access_type='STAFF' and revoked_at is null; end if; end $$;
grant execute on function public.set_staff_portal_activation(uuid,boolean,text) to authenticated;
create or replace function public.set_staff_portal_pin(p_staff_id uuid,p_pin text,p_reason text) returns void language plpgsql security definer set search_path=public,extensions as $$ begin if not public.can_administer() then raise exception 'Acceso administrativo requerido.'; end if; if p_pin !~ '^\d{4}$' then raise exception 'El PIN debe contener exactamente 4 números.'; end if; if nullif(trim(p_reason),'') is null then raise exception 'La razón del cambio es obligatoria.'; end if; update public.staff set pin_hash=crypt(p_pin,gen_salt('bf',10)),pin_updated_at=now(),portal_enabled=true,portal_activated_at=coalesce(portal_activated_at,now()),portal_password_change_required=true,approval_reason=p_reason,updated_by=auth.uid() where id=p_staff_id and deleted_at is null; if not found then raise exception 'Staff no encontrado.'; end if; update public.portal_access_sessions set revoked_at=now() where staff_id=p_staff_id and access_type='STAFF' and revoked_at is null; end $$;
create or replace function public.mark_staff_portal_invitation_sent(p_staff_id uuid) returns void language plpgsql security definer set search_path=public as $$ begin if not public.can_administer() then raise exception 'Acceso administrativo requerido.'; end if; update public.staff set portal_invitation_sent_at=now(),updated_by=auth.uid() where id=p_staff_id and deleted_at is null; end $$;
grant execute on function public.mark_staff_portal_invitation_sent(uuid) to authenticated;
create or replace function public.authenticate_staff_portal(p_rut text,p_pin text,p_ip_hash text,p_user_agent text,p_device text) returns table(session_token text,staff_id uuid,expires_at timestamptz) language plpgsql security definer set search_path=public,extensions as $$ declare normalized text:=upper(regexp_replace(coalesce(p_rut,''),'[^0-9K]','','g'));rut_hash text:=encode(digest(normalized,'sha256'),'hex');member public.staff%rowtype;token text;expiry timestamptz:=now()+interval '12 hours'; begin select * into member from public.staff where upper(regexp_replace(coalesce(rut,''),'[^0-9K]','','g'))=normalized and status='ACTIVE' and deleted_at is null limit 1; if member.id is null or not member.portal_enabled or member.pin_hash is null or crypt(coalesce(p_pin,''),member.pin_hash)<>member.pin_hash then member.id:=null; end if; insert into public.portal_access_attempts(access_type,normalized_rut_hash,succeeded,staff_id,ip_hash,user_agent,device) values('STAFF',rut_hash,member.id is not null,member.id,p_ip_hash,p_user_agent,p_device); if member.id is null then return; end if; token:=encode(gen_random_bytes(32),'hex'); insert into public.portal_access_sessions(access_type,staff_id,token_hash,expires_at,ip_hash,user_agent,device) values('STAFF',member.id,encode(digest(token,'sha256'),'hex'),expiry,p_ip_hash,p_user_agent,p_device); insert into public.timeline_events(staff_id,event_type,title,description,orbit_event_id,actor_label,source,action,entity_type,entity_id,human_message,correlation_id) values(member.id,'STAFF_PORTAL_ACCESS','Acceso al portal de Staff.','Acceso validado mediante RUT y credencial.','ORB-STAFF-'||member.id,'Staff','Staff','STAFF_PORTAL_ACCESS','Staff',member.id,'El colaborador accedió correctamente a su portal.',gen_random_uuid()::text); return query select token,member.id,expiry; end $$;
revoke all on function public.authenticate_staff_portal(text,text,text,text,text) from public,anon,authenticated;
grant execute on function public.authenticate_staff_portal(text,text,text,text,text) to service_role;
commit;
